                            is_top = True

                    # Check vertical edges
                    is_left = False
                    is_right = False

                    if tc == c:
                        # Left edge
                        all_left = True
                        for k in range(r, tr + 1):
                            if grid[k][c] != 2:
                                all_left = False
                        is_left = all_left

                    if tc == tc:
                        # Right edge check
                        valid = True
                        for k in range(r, tr + 1):
                            if grid[k][tc] != 2:
                                valid = False
                                break
                        is_right = valid

